insert into MST_CUSTOMER_INFO(CUSTOMER_ID, CUSTOMER_NAME, CUSTOMER_ABBR, CUSTOMER_TYPE, IS_ISSUER, IS_ASSTE_MANAGER, IS_TRUSTER, IS_SALER, IS_FINANCIER, IS_GUARANTEE, IS_RATING_AGENCIES, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, IS_PLEDGOR, IS_DEPOSIT_BANK, IS_INVEST_ADVISER, IS_BROKER, IS_COUNTER, IS_BANK, IS_FUTURE_COM) select de.CUSTOMER_ID, de.CUSTOMER_NAME, de.CUSTOMER_ABBR, de.CUSTOMER_TYPE, de.IS_ISSUER, de.IS_ASSTE_MANAGER, de.IS_TRUSTER, de.IS_SALER, de.IS_FINANCIER, de.IS_GUARANTEE, de.IS_RATING_AGENCIES, de.CREATE_USER, de.CREATE_DEPT, de.CREATE_TIME, de.UPDATE_USER, de.UPDATE_TIME, de.IS_PLEDGOR, de.IS_DEPOSIT_BANK, de.IS_INVEST_ADVISER, de.IS_BROKER, de.IS_COUNTER, de.IS_BANK, de.IS_FUTURE_COM from ( select TEMP.* from (
SELECT #{item.customerName,jdbcType=VARCHAR} CUSTOMER_NAME, #{item.customerAbbr,jdbcType=VARCHAR} CUSTOMER_ABBR, #{item.customerType,jdbcType=VARCHAR} CUSTOMER_TYPE, #{item.isIssuer,jdbcType=VARCHAR} IS_ISSUER, #{item.isAssteManager,jdbcType=VARCHAR} IS_ASSTE_MANAGER, #{item.isTruster,jdbcType=VARCHAR} IS_TRUSTER, #{item.isSaler,jdbcType=VARCHAR} IS_SALER, #{item.isFinancier,jdbcType=VARCHAR} IS_FINANCIER, #{item.isGuarantee,jdbcType=VARCHAR} IS_GUARANTEE, #{item.isRatingAgencies,jdbcType=VARCHAR} IS_RATING_AGENCIES, #{item.isPledgor,jdbcType=VARCHAR} IS_PLEDGOR, #{item.isDepositBank,jdbcType=VARCHAR} IS_DEPOSIT_BANK, #{item.isInvestAdviser,jdbcType=VARCHAR} IS_INVEST_ADVISER, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, now() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.isBroker,jdbcType=VARCHAR} IS_BROKER, #{item.isCounter,jdbcType=VARCHAR} IS_COUNTER, #{item.isBank,jdbcType=VARCHAR} IS_BANK, #{item.isFutureCom,jdbcType=VARCHAR} IS_FUTURE_COM, #{item.customerId,jdbcType=VARCHAR} CUSTOMER_ID FROM DUAL
) TEMP where not exists (select 1 from MST_CUSTOMER_INFO CII where CII.CUSTOMER_ID = TEMP.CUSTOMER_ID) ) de ;
UPDATE MST_CUSTOMER_INFO as A, ( select TEMP.* from (
SELECT #{item.customerName,jdbcType=VARCHAR} CUSTOMER_NAME, #{item.customerAbbr,jdbcType=VARCHAR} CUSTOMER_ABBR, #{item.customerType,jdbcType=VARCHAR} CUSTOMER_TYPE, #{item.isIssuer,jdbcType=VARCHAR} IS_ISSUER, #{item.isAssteManager,jdbcType=VARCHAR} IS_ASSTE_MANAGER, #{item.isTruster,jdbcType=VARCHAR} IS_TRUSTER, #{item.isSaler,jdbcType=VARCHAR} IS_SALER, #{item.isFinancier,jdbcType=VARCHAR} IS_FINANCIER, #{item.isGuarantee,jdbcType=VARCHAR} IS_GUARANTEE, #{item.isRatingAgencies,jdbcType=VARCHAR} IS_RATING_AGENCIES, #{item.isPledgor,jdbcType=VARCHAR} IS_PLEDGOR, #{item.isDepositBank,jdbcType=VARCHAR} IS_DEPOSIT_BANK, #{item.isInvestAdviser,jdbcType=VARCHAR} IS_INVEST_ADVISER, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, now() CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, now() UPDATE_TIME, #{item.isBroker,jdbcType=VARCHAR} IS_BROKER, #{item.isCounter,jdbcType=VARCHAR} IS_COUNTER, #{item.isBank,jdbcType=VARCHAR} IS_BANK, #{item.isFutureCom,jdbcType=VARCHAR} IS_FUTURE_COM, #{item.customerId,jdbcType=VARCHAR} CUSTOMER_ID FROM DUAL
) TEMP ) AS B SET A.CUSTOMER_NAME = B.CUSTOMER_NAME, A.CUSTOMER_ABBR = B.CUSTOMER_ABBR, A.CUSTOMER_TYPE = B.CUSTOMER_TYPE, A.IS_ISSUER = B.IS_ISSUER, A.IS_ASSTE_MANAGER = B.IS_ASSTE_MANAGER, A.IS_TRUSTER = B.IS_TRUSTER, A.IS_SALER = B.IS_SALER, A.IS_FINANCIER = B.IS_FINANCIER, A.IS_GUARANTEE = B.IS_GUARANTEE, A.IS_RATING_AGENCIES = B.IS_RATING_AGENCIES, A.IS_PLEDGOR = B.IS_PLEDGOR, A.IS_DEPOSIT_BANK = B.IS_DEPOSIT_BANK, A.IS_INVEST_ADVISER = B.IS_INVEST_ADVISER, A.CREATE_USER = B.CREATE_USER, A.CREATE_DEPT = B.CREATE_DEPT, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME, A.IS_BROKER = B.IS_BROKER, A.IS_COUNTER = B.IS_COUNTER, A.IS_BANK = B.IS_BANK, A.IS_FUTURE_COM = B.IS_FUTURE_COM where A.CUSTOMER_ID = B.CUSTOMER_ID;
